package pe.edu.upeu.entregable1.modelo;// las properties de JavaFXimport javafx.beans.property.IntegerProperty;import javafx.beans.property.SimpleIntegerProperty;import javafx.beans.property.SimpleStringProperty;import javafx.beans.property.StringProperty;public class Persona {    // CAMBIO: atributos simples -> properties de JavaFX    private final IntegerProperty idPersona = new SimpleIntegerProperty(this, "idPersona");    private final StringProperty nombres = new SimpleStringProperty(this, "nombres");    private final StringProperty apellidos = new SimpleStringProperty(this, "apellidos");    private final StringProperty dni = new SimpleStringProperty(this, "dni");    // telefono pasa de int a String (en la base de datos es TEXT)    private final StringProperty telefono = new SimpleStringProperty(this, "telefono");    public Persona() {    }    public Persona(int idPersona, String nombres, String apellidos, String dni, String telefono) {        setIdPersona(idPersona);        setNombres(nombres);        setApellidos(apellidos);        setDni(dni);        setTelefono(telefono);    }    // ---------- idPersona ----------    public final int getIdPersona() {        return idPersona.get();    }    public final void setIdPersona(int value) {        idPersona.set(value);    }    public final IntegerProperty idPersonaProperty() {        return idPersona;    }    // ---------- nombres ----------    public final String getNombres() {        return nombres.get();    }    public final void setNombres(String value) {        nombres.set(value);    }    public final StringProperty nombresProperty() {        return nombres;    }    // ---------- apellidos ----------    public final String getApellidos() {        return apellidos.get();    }    public final void setApellidos(String value) {        apellidos.set(value);    }    public final StringProperty apellidosProperty() {        return apellidos;    }    // ---------- dni ----------    public final String getDni() {        return dni.get();    }    public final void setDni(String value) {        dni.set(value);    }    public final StringProperty dniProperty() {        return dni;    }    // ---------- telefono ----------    public final String getTelefono() {        return telefono.get();    }    public final void setTelefono(String value) {        telefono.set(value);    }    public final StringProperty telefonoProperty() {        return telefono;    }    // metodo polimorfismo (no cambia)    public void mostrarInfo(Persona p) {    }}